根据规范（在持锁下先置 `ready` 再 `notify`、waiter 用 `while !ready` 等待并每次唤醒后重检），完整程序如下：

```rust
use concir_sync::Semaphore;
use std::sync::{Arc, Condvar, Mutex};
use std::thread;

struct Shared {
    ready: bool,
}

fn waiter(m: Arc<Mutex<Shared>>, cv: Arc<Condvar>) {
    let mut guard = m.lock().unwrap();
    while !guard.ready {
        guard = cv.wait(guard).unwrap();
    }
}

fn notifier(m: Arc<Mutex<Shared>>, cv: Arc<Condvar>) {
    let mut guard = m.lock().unwrap();
    guard.ready = true;
    cv.notify_one();
}

fn main() {
    let sem = Semaphore::new(2);

    let m = Arc::new(Mutex::new(Shared { ready: false }));
    let cv = Arc::new(Condvar::new());

    let m_w = Arc::clone(&m);
    let cv_w = Arc::clone(&cv);
    let sem_w = sem.clone();
    let waiter_handle = thread::spawn(move || {
        let _permit = sem_w.acquire();
        waiter(m_w, cv_w);
    });

    let m_n = Arc::clone(&m);
    let cv_n = Arc::clone(&cv);
    let sem_n = sem.clone();
    let notifier_handle = thread::spawn(move || {
        let _permit = sem_n.acquire();
        notifier(m_n, cv_n);
    });

    waiter_handle.join().unwrap();
    notifier_handle.join().unwrap();

    let ready = m.lock().unwrap().ready;
    println!("DONE ready={}", ready);
}
```
